package hu.chefrenting.api.dto;

import com.fasterxml.jackson.databind.annotation.JsonDeserialize;
import jakarta.validation.constraints.NotNull;
import java.time.LocalDate;

/**
 * Body of POST /api/berlesek. There is no id and no totalPrice: the id is generated by the
 * database and the total price is always calculated by the server (extra JSON fields are ignored).
 */
public record BerlesRequest(
        @NotNull(message = "Az uid megadása kötelező.") Integer uid,
        @NotNull(message = "A chefId megadása kötelező.") Integer chefId,
        @NotNull(message = "A startDate (kezdő dátum) megadása kötelező.")
        @JsonDeserialize(using = LenientDateDeserializer.class) LocalDate startDate,
        @NotNull(message = "Az endDate (záró dátum) megadása kötelező.")
        @JsonDeserialize(using = LenientDateDeserializer.class) LocalDate endDate,
        @NotNull(message = "A dailyRate (napi díj) megadása kötelező.") Integer dailyRate,
        @NotNull(message = "A baseFee (alapdíj) megadása kötelező.") Integer baseFee) {
}
